+                        "definition": {
+                          "preprocessors" : [{
+                            "one_hot_encoding": {
+                              "field": "product_type",
+                              "hot_map": {
+                                "TV": "type_tv",
+                                "VCR": "type_vcr",
+                                "Laptop": "type_laptop"
+                              }
+                            }
+                          }],
+                          "trained_model": {
+                            "ensemble": {
+                              "feature_names": [],
+                              "target_type": "regression",
+                              "trained_models": [
+                              {
+                                "tree": {
+                                  "feature_names": [
+                                    "avg_cost", "type_tv", "type_vcr", "type_laptop"
+                                  ],
+                                  "tree_structure": [
+                                  {
+                                    "node_index": 0,
+                                    "split_feature": 0,
+                                    "split_gain": 12,
+                                    "threshold": 38,
+                                    "decision_type": "lte",
+                                    "default_left": true,
+                                    "left_child": 1,
+                                    "right_child": 2
+                                  },
+                                  {
+                                    "node_index": 1,
+                                    "leaf_value": 5.0
+                                  },
+                                  {
+                                    "node_index": 2,
+                                    "leaf_value": 2.0
+                                  }
+                                  ],
+                                  "target_type": "regression"
+                                }
+                              }
+                              ]
+                            }
+                          }
+                        }
+                      }""");
+    }
+
+    @SuppressWarnings("unchecked")
+    public void testInference() throws Exception {
+        Response response = infer("a-complex-regression-model", "{\"item\": \"TV\", \"avg_cost\": 300}");
+        assertThat(
+            (List<Double>)XContentMapValues.extractValue("inference_results.regression-value", responseAsMap(response)),
+            equalTo(List.of(2.0))
