+            String email = input.readOptionalString();
+            boolean enabled = input.readBoolean();
+            User outerUser = new User(username, roles, fullName, email, metadata, enabled);
+            boolean hasInnerUser = input.readBoolean();
+            if (hasInnerUser) {
