+        long getRemainingMemory(Node n) {
+            return remainingNodeMemory.get(n);
+        }
+
+        int getRemainingThreads(Model m) {
+            return remainingModelAllocations.get(m) * m.threadsPerAllocation();
+        }
+
+        int getRemainingAllocations(Model m) {
