+    private List<Model> randomModels(int scale, double load, List<Node> nodes) {
+        List<Model> models = new ArrayList<>();
+        for (int i = 0; i < Math.max(2, Math.round(load * (1 + 8 * scale))); i++) {
+            models.add(randomModel(String.valueOf(i)));
+        }
+        return models;
+    }
