+    private static Model randomModel(String idSuffix) {
+        return new Model(
+            "m_" + idSuffix,
+            randomLongBetween(ByteSizeValue.ofMb(100).getBytes(), ByteSizeValue.ofGb(10).getBytes()),
+            randomIntBetween(1, 32),
+            randomIntBetween(1, 4),
+            Map.of()
+        );
+    }
