+public class QuestionAnsweringProcessorTests extends ESTestCase {
+
+    private static final double[] START_TOKEN_SCORES = new double[] {
+        1.6665655,
+        -7.988514,
+        -8.249796,
+        .529973,
+        -8.46703,
+        -8.345977,
+        -8.459701,
+        -8.260341,
