+                        "leaf_value": 2
+                      }
+                    ],
+                    "target_type": "regression"
+                  }
+                },
+                {
+                  "tree": {
+                    "feature_names": [
+                      "col2_encoded",
+                      "col3_encoded",
+                      "col4"
+                    ],
+                    "tree_structure": [
+                      {
+                        "node_index": 0,
+                        "split_feature": 0,
+                        "split_gain": 12.0,
+                        "threshold": 10.0,
