+                    "target_type": "regression"
+                  }
+                }
+              ]
+            }
+          }
+        }""";
+
+    private static final String REGRESSION_CONFIG = """
+        {
+            "input": {
+                "field_names": [
+                    "col1",
+                    "col2",
+                    "col3",
+                    "col4"
+                ]
+            },
+            "description": "test model for regression",
+            "inference_config": {
